def row_majority_adjust(grid, ratio=0.7):
    out = grid.copy()
    for i in range(out.shape[0]):
        row = out[i]
        ones_ratio = row.sum() / len(row)
        if ones_ratio > ratio:
            out[i] = 1
        elif (1 - ones_ratio) > ratio:
            out[i] = 0
    return out

